/* Contenido de «Inglés para Atención a Clientes y Call Center». Archivo generado con herramientas/dividir-catalogo.js: no se edita a mano. */
window.MARA_CONTENIDO("c-ingles-servicio",{"l":{"c-ingles-servicio-m1-l1":[{"tipo":"destacado","texto":"<b>Antes de empezar:</b> este es un <b>curso libre de capacitación</b> con constancia de Instituto Mara. <b>No es una certificación de inglés</b> (como TOEFL, Cambridge, IELTS u otras) ni tiene validez oficial ante la SEP o el CONOCER. Si una empresa te pide un nivel certificado, tendrás que presentar ese examen por tu cuenta. Lo que sí hace este curso es darte las frases, la pronunciación y la práctica que se usan todos los días en la atención a clientes en inglés. Te recomendamos tener al menos un nivel <b>A2</b>; si vienes de cero, empieza por nuestro Inglés A1 y A2."},{"tipo":"texto","texto":"En un call center bilingüe de Monterrey, Guadalajara o la Ciudad de México, o en la recepción de un hotel en Cancún, los primeros <b>diez segundos</b> de la llamada marcan el tono. Casi todas las empresas tienen un <b>guion de apertura</b> (<i>opening script</i>) con tres partes: <b>1)</b> un saludo y el nombre de la empresa, <b>2)</b> tu nombre, y <b>3)</b> una pregunta abierta. Tu trabajo no es memorizarlo como robot, sino decirlo con voz clara, sonrisa y buen ritmo."},{"tipo":"tabla","titulo":"El saludo de guion, parte por parte","voz":true,"colVoz":1,"encabezados":["Parte","Frase","Español"],"filas":[["Saludo + empresa","Thank you for calling BlueRiver Wireless.","Gracias por llamar a BlueRiver Wireless."],["Saludo según la hora","Good morning / Good afternoon / Good evening.","Buenos días / Buenas tardes / Buenas noches."],["Tu nombre","My name is Daniela.","Mi nombre es Daniela."],["Pregunta abierta","How may I help you today?","¿En qué le puedo ayudar hoy?"],["Variante informal","How can I help you?","¿Cómo le ayudo?"],["Aviso de grabación","This call may be recorded for quality purposes.","Esta llamada puede ser grabada con fines de calidad."]],"nota":"<i>Good evening</i> es para saludar en la noche; <i>Good night</i> es solo para despedirse o irse a dormir. En el teléfono casi nunca se dice «Good night» al contestar."},{"tipo":"dialogo","titulo":"Diálogo — Primera llamada del turno en Guadalajara","lineas":[{"quien":"Agent","en":"Good morning, thank you for calling BlueRiver Wireless. My name is Daniela. How may I help you today?","es":"Buenos días, gracias por llamar a BlueRiver Wireless. Mi nombre es Daniela. ¿En qué le puedo ayudar hoy?"},{"quien":"Customer","en":"Hi, Daniela. I'm calling about my bill. I think I was charged twice.","es":"Hola, Daniela. Llamo por mi factura. Creo que me cobraron dos veces."},{"quien":"Agent","en":"I'm sorry to hear that. I'll be happy to look into it for you. May I have your name, please?","es":"Lamento escuchar eso. Con gusto lo reviso. ¿Me da su nombre, por favor?"},{"quien":"Customer","en":"Sure, it's Robert Miller.","es":"Claro, es Robert Miller."},{"quien":"Agent","en":"Thank you, Mr. Miller. Let me pull up your account.","es":"Gracias, señor Miller. Permítame abrir su cuenta."}]},{"tipo":"comparar","titulo":"Cómo suena un buen arranque","malTitulo":"Suena frío o apresurado","mal":"<i>Yes? What do you want?</i><br><i>Hello, BlueRiver, tell me.</i><br>Decir el guion tan rápido que no se entiende tu nombre.","bienTitulo":"Suena profesional","bien":"<i>Thank you for calling BlueRiver Wireless. My name is Daniela. How may I help you today?</i><br>Pausa breve después del nombre de la empresa y después de tu nombre."},{"tipo":"practica","rotulo":"Elige la mejor opción","preguntas":[{"p":"Son las 4 p. m. ¿Cómo saludas?","ops":["Good morning","Good night","Good afternoon"],"correcta":2,"explica":"De mediodía a las 5 o 6 p. m. se usa <b>Good afternoon</b>."},{"p":"¿Cuál es la pregunta abierta más profesional?","ops":["How may I help you today?","What is your problem?","Why are you calling?"],"correcta":0,"explica":"<i>How may I help you?</i> es cortés y deja hablar al cliente."},{"p":"«Con gusto lo reviso» se dice…","ops":["I'm happy for check it.","I'll be happy to look into it.","I like to check it."],"correcta":1},{"p":"«Permítame abrir su cuenta» se dice…","ops":["Wait, I open your account.","Let me pull up your account.","Give me your account open."],"correcta":1,"explica":"<i>Pull up</i> = abrir o traer en pantalla un expediente."},{"p":"El cliente dice su nombre. ¿Qué contestas?","ops":["Thank you, Mr. Miller.","OK, Miller.","Good, Robert Miller."],"correcta":0}]},{"tipo":"ordenar","rotulo":"Arma el saludo de guion","voz":true,"items":[{"frase":"Thank you for calling BlueRiver Wireless","es":"Gracias por llamar a BlueRiver Wireless"},{"frase":"My name is Daniela","es":"Mi nombre es Daniela"},{"frase":"How may I help you today?","es":"¿En qué le puedo ayudar hoy?"},{"frase":"I'll be happy to help you with that","es":"Con gusto le ayudo con eso"}]},{"tipo":"pronunciar","rotulo":"Practica tu apertura en voz alta","frases":[{"en":"Thank you for calling. My name is Daniela.","pron":"zank iu for cóling mai néim is daniéla","es":"Gracias por llamar. Mi nombre es Daniela."},{"en":"How may I help you today?","pron":"jáu méi ai jelp iu tudéi","es":"¿En qué le puedo ayudar hoy?"},{"en":"I'll be happy to look into it for you.","pron":"ail bi jápi tu luk íntu it for iu","es":"Con gusto lo reviso por usted."},{"en":"This call may be recorded for quality purposes.","es":"Esta llamada puede ser grabada con fines de calidad."}]},{"tipo":"clave","items":["Apertura: saludo + empresa → tu nombre → <i>How may I help you today?</i>","Di el guion con pausas y sonrisa; no como robot ni a toda velocidad.","Este curso es libre, con constancia de Instituto Mara; no es una certificación de inglés."]}],"c-ingles-servicio-m1-l2":[{"tipo":"texto","texto":"Antes de revisar una cuenta, casi siempre tienes que <b>verificar la identidad</b> del cliente. Esto protege sus datos, pero si lo haces con frases secas suena a interrogatorio. El secreto es <b>explicar para qué</b> y usar <i>may I, could you</i> y <i>please</i>. Pide <b>solo los datos que indique el procedimiento de tu empresa</b>: nunca pidas contraseñas, números completos de tarjeta ni otros datos que tu guion no incluya."},{"tipo":"tabla","titulo":"Frases para verificar sin sonar a interrogatorio","voz":true,"colVoz":1,"encabezados":["Para…","Frase","Español"],"filas":[["Explicar","Before we continue, I need to verify your identity.","Antes de continuar, necesito verificar su identidad."],["Pedir nombre","May I have your full name, please?","¿Me da su nombre completo, por favor?"],["Pedir un dato","Could you please confirm the phone number on the account?","¿Podría confirmar el teléfono registrado en la cuenta?"],["Pedir fecha","Could you verify your date of birth for me?","¿Me confirma su fecha de nacimiento?"],["Pedir deletreo","Could you spell that for me, please?","¿Me lo deletrea, por favor?"],["Confirmar","Thank you. You have been verified.","Gracias. Ya quedó verificado."]]},{"tipo":"texto","texto":"Por teléfono, muchas letras suenan igual: <b>B, D, E, P, T, V</b> o <b>M</b> y <b>N</b>. Por eso se usa el <b>alfabeto fonético NATO</b> (también llamado alfabeto radiofónico o de la OTAN): cada letra tiene una palabra clave. Se dice <i>«M as in Mike»</i> o, más rápido, <i>«M, Mike»</i>. Apréndelo de memoria: en un call center lo usarás decenas de veces por turno."},{"tipo":"tarjetas","rotulo":"Alfabeto NATO (primera mitad)","voz":true,"instruccion":"Di en voz alta la palabra clave de cada letra antes de voltear.","tarjetas":[{"frente":"A","reverso":"Alfa","ej":"A as in Alfa"},{"frente":"B","reverso":"Bravo","ej":"B as in Bravo"},{"frente":"C","reverso":"Charlie","ej":"C as in Charlie"},{"frente":"D","reverso":"Delta","ej":"D as in Delta"},{"frente":"E","reverso":"Echo","ej":"E as in Echo"},{"frente":"F","reverso":"Foxtrot","ej":"F as in Foxtrot"},{"frente":"G","reverso":"Golf","ej":"G as in Golf"},{"frente":"H","reverso":"Hotel","ej":"H as in Hotel"},{"frente":"I","reverso":"India","ej":"I as in India"},{"frente":"J","reverso":"Juliett","ej":"J as in Juliett"},{"frente":"K","reverso":"Kilo","ej":"K as in Kilo"},{"frente":"L","reverso":"Lima","ej":"L as in Lima"},{"frente":"M","reverso":"Mike","ej":"M as in Mike"}]},{"tipo":"tarjetas","rotulo":"Alfabeto NATO (segunda mitad)","voz":true,"instruccion":"Ahora la segunda mitad. Después intenta deletrear tu nombre completo.","tarjetas":[{"frente":"N","reverso":"November","ej":"N as in November"},{"frente":"O","reverso":"Oscar","ej":"O as in Oscar"},{"frente":"P","reverso":"Papa","ej":"P as in Papa"},{"frente":"Q","reverso":"Quebec","ej":"Q as in Quebec"},{"frente":"R","reverso":"Romeo","ej":"R as in Romeo"},{"frente":"S","reverso":"Sierra","ej":"S as in Sierra"},{"frente":"T","reverso":"Tango","ej":"T as in Tango"},{"frente":"U","reverso":"Uniform","ej":"U as in Uniform"},{"frente":"V","reverso":"Victor","ej":"V as in Victor"},{"frente":"W","reverso":"Whiskey","ej":"W as in Whiskey"},{"frente":"X","reverso":"X-ray","ej":"X as in X-ray"},{"frente":"Y","reverso":"Yankee","ej":"Y as in Yankee"},{"frente":"Z","reverso":"Zulu","ej":"Z as in Zulu (en EE. UU. la letra se dice «zi»)"}]},{"tipo":"dialogo","titulo":"Diálogo — Confirmar un correo electrónico","lineas":[{"quien":"Agent","en":"Could you spell your last name for me, please?","es":"¿Me deletrea su apellido, por favor?"},{"quien":"Customer","en":"Sure. It's Byrne. B-Y-R-N-E.","es":"Claro. Es Byrne. B-Y-R-N-E."},{"quien":"Agent","en":"Let me read it back to you: B as in Bravo, Y as in Yankee, R as in Romeo, N as in November, E as in Echo. Is that correct?","es":"Se lo repito: B de Bravo, Y de Yankee, R de Romeo, N de November, E de Echo. ¿Es correcto?"},{"quien":"Customer","en":"That's right.","es":"Así es."},{"quien":"Agent","en":"And the email on file is kbyrne at gmail dot com?","es":"¿Y el correo registrado es kbyrne arroba gmail punto com?"},{"quien":"Customer","en":"Yes, all lowercase.","es":"Sí, todo en minúsculas."}]},{"tipo":"practica","rotulo":"¿Entendiste el deletreo?","preguntas":[{"p":"El cliente dice «T as in Tango, O as in Oscar, M as in Mike». ¿Qué nombre es?","ops":["Tim","Tom","Tony"],"correcta":1},{"p":"¿Cómo se lee <i>@</i> en un correo?","ops":["arroba","dot","at"],"correcta":2,"explica":"<b>@</b> = <i>at</i>; <b>.</b> = <i>dot</i>; <b>_</b> = <i>underscore</i>; <b>-</b> = <i>dash</i> o <i>hyphen</i>."},{"p":"«Se lo repito para confirmar» se dice…","ops":["Let me read it back to you.","I repeat you it.","Let me say again for you."],"correcta":0},{"p":"¿Cuál es la forma más cortés de pedir un dato?","ops":["Give me your phone number.","Could you please confirm the phone number on the account?","Phone number?"],"correcta":1},{"p":"«Todo en minúsculas» se dice…","ops":["all capital letters","all small caps please","all lowercase"],"correcta":2,"explica":"<i>lowercase</i> = minúsculas · <i>uppercase</i> o <i>capital letters</i> = mayúsculas."}]},{"tipo":"completar","rotulo":"Completa la verificación","voz":true,"items":[{"frase":"Before we continue, I need to ___ your identity.","resp":["verify","confirm"],"es":"Antes de continuar, necesito verificar su identidad."},{"frase":"Could you ___ that for me, please?","resp":["spell"],"es":"¿Me lo deletrea, por favor?"},{"frase":"P as in ___, A as in Alfa, Z as in Zulu.","resp":["Papa"],"es":"P de Papa, A de Alfa, Z de Zulu."},{"frase":"The email on file is maria ___ outlook dot com.","resp":["at"],"es":"El correo registrado es maria arroba outlook punto com."},{"frase":"Thank you. You have been ___.","resp":["verified"],"es":"Gracias. Ya quedó verificado."}]},{"tipo":"clave","items":["Explica para qué verificas y pide con <i>May I…? / Could you please…?</i>; solo los datos que marque tu procedimiento.","Alfabeto NATO: <i>B as in Bravo, M as in Mike</i>. Repite siempre el dato con <i>Let me read it back to you</i>.","Correos: <i>at</i> (@), <i>dot</i> (.), <i>underscore</i> (_), <i>dash</i> (-), <i>lowercase</i>."]}],"c-ingles-servicio-m1-l3":[{"tipo":"texto","texto":"Un error con un número cuesta caro: un reembolso a la cuenta equivocada o un paquete que llega a otra ciudad. Tres diferencias con México te van a salvar: <b>1)</b> en EE. UU. la fecha se escribe <b>mes/día/año</b> (<i>03/04/2026</i> es el <b>4 de marzo</b>, no el 3 de abril); <b>2)</b> la dirección empieza por el <b>número</b> y luego la calle; <b>3)</b> los teléfonos se dicen <b>dígito por dígito</b>, en grupos de 3-3-4."},{"tipo":"tabla","titulo":"Cómo se dicen","voz":true,"colVoz":1,"encabezados":["Dato","Se dice","Nota"],"filas":[["(512) 555-0147","five one two, five five five, oh one four seven","El cero se dice «oh» o «zero»; pausa entre grupos"],["$49.99","forty-nine ninety-nine","O «forty-nine dollars and ninety-nine cents»"],["03/04/2026","March fourth, twenty twenty-six","Mes primero; el día en ordinal"],["1450 Oak Street, Apt. 3B","fourteen fifty Oak Street, apartment three B","Números de casa en pares: 14-50"],["Austin, TX 78701","Austin, Texas, seven eight seven oh one","Estado en dos letras; ZIP code de cinco dígitos"],["13 / 30","thirteen / thirty","Acentúa distinto: thir<b>teen</b> contra <b>thir</b>ty"]],"nota":"Si dudas entre 15 y 50, pregunta: <i>Is that one-five or five-zero?</i> Es normal y profesional confirmar."},{"tipo":"escuchar","rotulo":"Escucha los datos como los dice un cliente","frases":[{"en":"My number is two one four, five five five, oh eight two three.","es":"Mi número es 214 555 0823."},{"en":"The order was placed on July twelfth.","es":"El pedido se hizo el 12 de julio."},{"en":"I live at twenty-two ten Maple Avenue, Suite four hundred.","es":"Vivo en 2210 Maple Avenue, Suite 400."},{"en":"The total was one hundred and fifteen dollars.","pron":"de tóutal uas uan jándred and fiftín dólars","es":"El total fue de 115 dólares."},{"en":"My ZIP code is nine oh two one oh.","es":"Mi código postal es 90210."}]},{"tipo":"practica","rotulo":"Elige la respuesta correcta","preguntas":[{"p":"Un cliente de EE. UU. escribe <i>05/06/2026</i>. ¿Qué fecha es?","ops":["5 de junio de 2026","6 de mayo de 2026","Mayo o junio, no se sabe"],"correcta":1,"explica":"En EE. UU. va primero el mes: 05 = mayo, 06 = día 6."},{"p":"¿Cómo se dice <i>$19.95</i> de forma natural?","ops":["nineteen ninety-five","one nine nine five","nineteen point ninety-five"],"correcta":0},{"p":"El cliente dice «fifty». No estás segura si fue 15 o 50. ¿Qué dices?","ops":["OK, fifteen.","Is that one-five or five-zero?","Say it again slowly, please, slowly."],"correcta":1},{"p":"¿En qué orden va una dirección en EE. UU.?","ops":["Calle, número, ciudad","Ciudad, calle, número","Número, calle, ciudad, estado, ZIP"],"correcta":2},{"p":"¿Cómo se dice la fecha <i>November 1</i>?","ops":["November one","November first","November the one"],"correcta":1,"explica":"Los días se dicen en ordinal: <i>first, second, third, fourth…</i>"}]},{"tipo":"relacionar","rotulo":"Relaciona la abreviatura con su significado","voz":true,"pares":[["St.","Street (calle)"],["Ave.","Avenue (avenida)"],["Apt.","Apartment (departamento)"],["Blvd.","Boulevard (bulevar)"],["Ste.","Suite (oficina o local)"],["ZIP code","Código postal"]]},{"tipo":"completar","rotulo":"Completa el dato","voz":true,"items":[{"frase":"Your order will arrive on March ___ (3).","resp":["third","3rd"],"es":"Su pedido llegará el 3 de marzo."},{"frase":"The total is twenty-nine ___ (99 centavos).","resp":["ninety-nine","ninety nine"],"es":"El total es de 29.99."},{"frase":"Could you confirm your ___ code, please?","resp":["ZIP","zip"],"es":"¿Me confirma su código postal, por favor?"},{"frase":"My phone number ends in four, seven, ___, two. (0)","resp":["oh","zero"],"es":"Mi número termina en 4-7-0-2."},{"frase":"I live in ___ 5C. (departamento)","resp":["apartment","Apartment","Apt."],"es":"Vivo en el departamento 5C."}]},{"tipo":"pronunciar","rotulo":"Dilo en voz alta, con pausas","frases":[{"en":"Five one two, five five five, oh one four seven.","es":"512 555 0147."},{"en":"Your appointment is on Tuesday, April twenty-second.","pron":"iór apóintment is on tiúsdei éipril tuénti sékond","es":"Su cita es el martes 22 de abril."},{"en":"Thirteen, not thirty. One-three.","pron":"zertín not zérti uan zri","es":"Trece, no treinta. Uno-tres."},{"en":"Is that one-five or five-zero?","es":"¿Es uno-cinco o cinco-cero?"}]},{"tipo":"clave","items":["Fecha en EE. UU.: <b>mes/día/año</b>, y el día en ordinal (<i>March fourth</i>).","Teléfonos dígito por dígito en grupos 3-3-4; precios en pares (<i>forty-nine ninety-nine</i>).","Ante la duda (15/50, 13/30), confirma: <i>Is that one-five or five-zero?</i>"]}],"c-ingles-servicio-m1-l4":[{"tipo":"texto","texto":"Pocas cosas molestan más a un cliente que quedarse en silencio sin saber qué pasa. Por eso la espera y la transferencia tienen reglas claras: <b>pide permiso</b>, <b>di cuánto tiempo</b> o para qué, y <b>agradece al regresar</b>. Al cerrar, resume lo que hiciste, pregunta si hay algo más y despídete con el guion de tu empresa."},{"tipo":"tabla","titulo":"Espera, transferencia y cierre","voz":true,"colVoz":1,"encabezados":["Momento","Frase","Español"],"filas":[["Pedir permiso","May I place you on a brief hold while I check that?","¿Le puedo poner en una breve espera mientras reviso eso?"],["Dar tiempo","It should take about two minutes.","Debe tomar unos dos minutos."],["Regresar","Thank you for holding, Ms. Lee.","Gracias por esperar, señora Lee."],["Transferir","I'm going to transfer you to our billing department.","Le voy a transferir a nuestro departamento de facturación."],["Explicar","They're the best team to help you with this.","Ellos son el mejor equipo para ayudarle con esto."],["Resumir","So, to recap: I've updated your address and…","Entonces, para resumir: actualicé su dirección y…"],["Algo más","Is there anything else I can help you with today?","¿Hay algo más en lo que le pueda ayudar hoy?"],["Despedida","Thank you for calling. Have a great day!","Gracias por llamar. ¡Que tenga un excelente día!"]]},{"tipo":"comparar","titulo":"Transferencia fría contra transferencia cálida","malTitulo":"Sin explicar","mal":"<i>Hold on.</i> (y se oye la música)<br>El cliente no sabe a dónde va ni por qué, y tiene que repetir todo.","bienTitulo":"Con explicación","bien":"<i>I'm going to transfer you to our technical support team. I'll stay on the line and explain your case, so you don't have to repeat it.</i>"},{"tipo":"dialogo","titulo":"Diálogo — Espera y cierre en un call center de Monterrey","lineas":[{"quien":"Agent","en":"May I place you on a brief hold while I review your last payment? It should take about two minutes.","es":"¿Le puedo poner en una breve espera mientras reviso su último pago? Debe tomar unos dos minutos."},{"quien":"Customer","en":"Sure, go ahead.","es":"Claro, adelante."},{"quien":"Agent","en":"Thank you for holding, Ms. Lee. I can see the payment was received on June third, so your account is up to date.","es":"Gracias por esperar, señora Lee. Veo que el pago se recibió el 3 de junio, así que su cuenta está al corriente."},{"quien":"Customer","en":"Oh, great. That's a relief.","es":"Ah, qué bien. Qué alivio."},{"quien":"Agent","en":"Is there anything else I can help you with today?","es":"¿Hay algo más en lo que le pueda ayudar hoy?"},{"quien":"Customer","en":"No, that's all. Thanks!","es":"No, es todo. ¡Gracias!"},{"quien":"Agent","en":"You're welcome. Thank you for calling BlueRiver Wireless. Have a great day!","es":"De nada. Gracias por llamar a BlueRiver Wireless. ¡Que tenga un excelente día!"}]},{"tipo":"practica","rotulo":"¿Qué dices en cada momento?","preguntas":[{"p":"Necesitas revisar algo con tu supervisor. ¿Qué dices primero?","ops":["Wait.","One moment, hold.","May I place you on a brief hold while I check that?"],"correcta":2},{"p":"Regresas de la espera. ¿Qué dices?","ops":["Thank you for holding.","I am back again now.","OK, listen."],"correcta":0},{"p":"«Le voy a transferir a facturación» se dice…","ops":["I'm going to pass you for billing.","I'm going to transfer you to our billing department.","I will send you in billing."],"correcta":1},{"p":"Terminaste de resolver. ¿Qué preguntas antes de despedirte?","ops":["Are we done?","Is there anything else I can help you with today?","Something more?"],"correcta":1},{"p":"La espera va a tardar más de lo dicho. ¿Qué haces?","ops":["Regresas, explicas y pides permiso para unos minutos más","Lo dejas en espera sin decir nada","Cuelgas y esperas a que vuelva a llamar"],"correcta":0,"explica":"Regresa a la línea: <i>Thank you for your patience. I need two more minutes. Is that OK?</i>"}]},{"tipo":"ordenar","rotulo":"Arma las frases del cierre","voz":true,"items":[{"frase":"Thank you for holding, Mr. Diaz","es":"Gracias por esperar, señor Díaz"},{"frase":"Is there anything else I can help you with?","es":"¿Hay algo más en lo que le pueda ayudar?"},{"frase":"Thank you for calling. Have a great day!","es":"Gracias por llamar. ¡Que tenga un excelente día!"}]},{"tipo":"pronunciar","rotulo":"Practica en voz alta","frases":[{"en":"May I place you on a brief hold?","pron":"méi ai pléis iu on a brif jóuld","es":"¿Le puedo poner en una breve espera?"},{"en":"Thank you for your patience.","pron":"zank iu for iór péishens","es":"Gracias por su paciencia."},{"en":"Is there anything else I can help you with today?","es":"¿Hay algo más en lo que le pueda ayudar hoy?"},{"en":"Have a great day!","es":"¡Que tenga un excelente día!"}]},{"tipo":"clave","items":["Espera: pide permiso, di cuánto tarda y agradece al volver (<i>Thank you for holding</i>).","Transfiere explicando a dónde y por qué; si puedes, haz una transferencia cálida.","Cierre: resume → <i>Is there anything else…?</i> → despedida de guion."]}],"c-ingles-servicio-m2-l1":[{"tipo":"texto","texto":"Cuando un cliente llama con un problema, primero necesita <b>sentirse escuchado</b>; después, que lo ayuden. Si saltas directo a la solución, aunque sea buena, el cliente siente que no le pusiste atención. El orden que funciona es: <b>1)</b> escuchar sin interrumpir, con pequeñas señales (<i>I see, OK, mm-hmm</i>); <b>2)</b> <b>parafrasear</b> para confirmar; <b>3)</b> mostrar <b>empatía</b>; y <b>4)</b> pasar a la acción."},{"tipo":"tabla","titulo":"Frases de escucha, paráfrasis y empatía","voz":true,"colVoz":1,"encabezados":["Para…","Frase","Español"],"filas":[["Señal de escucha","I see. / Go on. / Mm-hmm.","Ya veo. / Continúe. / Ajá."],["Parafrasear","So, if I understand correctly, your package hasn't arrived.","Entonces, si entiendo bien, su paquete no ha llegado."],["Parafrasear","Let me make sure I have this right…","Déjeme asegurarme de que lo entendí bien…"],["Empatía","I understand how frustrating that must be.","Entiendo lo frustrante que debe ser."],["Empatía","I can see why you're upset.","Entiendo por qué está molesto."],["Empatía","That's definitely not the experience we want for you.","Definitivamente esa no es la experiencia que queremos para usted."],["Pasar a la acción","Let's see what we can do to fix this.","Veamos qué podemos hacer para resolverlo."]],"nota":"<i>I understand how frustrating <b>that must be</b></i>: fíjate en el orden. No es «how frustrating must be that»."},{"tipo":"dialogo","titulo":"Diálogo — Un paquete que no llega","lineas":[{"quien":"Customer","en":"I ordered a laptop ten days ago, and it still hasn't arrived. The tracking hasn't changed since Monday.","es":"Pedí una laptop hace diez días y todavía no llega. El rastreo no ha cambiado desde el lunes."},{"quien":"Agent","en":"I see. Go on, please.","es":"Ya veo. Continúe, por favor."},{"quien":"Customer","en":"I need it for work next week. This is really stressful.","es":"La necesito para trabajar la próxima semana. Esto es muy estresante."},{"quien":"Agent","en":"So, if I understand correctly, your laptop hasn't arrived and the tracking hasn't been updated since Monday. Is that right?","es":"Entonces, si entiendo bien, su laptop no ha llegado y el rastreo no se actualiza desde el lunes. ¿Es correcto?"},{"quien":"Customer","en":"Exactly.","es":"Exacto."},{"quien":"Agent","en":"I understand how frustrating that must be, especially when you need it for work. Let's see what we can do to fix this.","es":"Entiendo lo frustrante que debe ser, sobre todo si la necesita para trabajar. Veamos qué podemos hacer para resolverlo."}]},{"tipo":"practica","rotulo":"Elige la mejor respuesta","preguntas":[{"p":"El cliente está a media explicación. ¿Qué haces?","ops":["Lo interrumpes con la solución","Das señales de escucha: <i>I see, go on</i>","Te quedas en silencio total"],"correcta":1,"explica":"Las señales cortas le dicen al cliente que sigues ahí, sin cortarlo."},{"p":"¿Cuál es una buena paráfrasis?","ops":["So, if I understand correctly, you were charged twice.","You said many things.","OK, OK, I understand everything."],"correcta":0},{"p":"¿Cuál frase de empatía es correcta?","ops":["I understand how frustrating must be that.","I understand how that frustrating is.","I understand how frustrating that must be."],"correcta":2},{"p":"«Entiendo por qué está molesto» se dice…","ops":["I see why you are angry with me.","I can see why you're upset.","I know you are crazy."],"correcta":1},{"p":"¿Qué va después de la empatía?","ops":["Una explicación larga de por qué no es tu culpa","Colgar la llamada","Pasar a la acción: <i>Let's see what we can do.</i>"],"correcta":2}]},{"tipo":"completar","rotulo":"Completa las frases de empatía","voz":true,"items":[{"frase":"I understand how ___ that must be.","resp":["frustrating"],"es":"Entiendo lo frustrante que debe ser."},{"frase":"So, if I understand ___, your order is missing an item.","resp":["correctly"],"es":"Entonces, si entiendo bien, a su pedido le falta un artículo."},{"frase":"Let me make ___ I have this right.","resp":["sure"],"es":"Déjeme asegurarme de que lo entendí bien."},{"frase":"That's definitely not the ___ we want for you.","resp":["experience"],"es":"Definitivamente esa no es la experiencia que queremos para usted."},{"frase":"Let's see what we can do to ___ this.","resp":["fix","solve","resolve"],"es":"Veamos qué podemos hacer para resolverlo."}]},{"tipo":"pronunciar","rotulo":"Dilo con voz tranquila y cálida","frases":[{"en":"I understand how frustrating that must be.","pron":"ai anderstánd jáu frastréiting dat mast bi","es":"Entiendo lo frustrante que debe ser."},{"en":"Let me make sure I have this right.","pron":"let mi méik shur ai jav dis ráit","es":"Déjeme asegurarme de que lo entendí bien."},{"en":"Let's see what we can do to fix this.","es":"Veamos qué podemos hacer para resolverlo."}]},{"tipo":"clave","items":["Orden: escuchar → parafrasear → empatía → acción.","Parafrasea con <i>So, if I understand correctly…</i> y cierra con <i>Is that right?</i>","Empatía natural: <i>I understand how frustrating that must be.</i>"]}],"c-ingles-servicio-m2-l2":[{"tipo":"texto","texto":"Una disculpa profesional <b>reconoce el problema</b> sin echarle la culpa a otra área, al sistema o al propio cliente. Y cuando hay algo que no puedes hacer por una <b>política</b> (<i>policy</i>) de la empresa, el truco es el <b>lenguaje positivo</b>: en lugar de empezar con «no se puede», empiezas con <b>lo que sí puedes hacer</b>. El cliente escucha la misma regla, pero con una salida."},{"tipo":"tabla","titulo":"Disculpas y políticas","voz":true,"colVoz":1,"encabezados":["Para…","Frase","Español"],"filas":[["Disculpa","I'm very sorry for the inconvenience.","Lamento mucho el inconveniente."],["Disculpa","I apologize for the delay with your order.","Me disculpo por el retraso con su pedido."],["Asumir","Thank you for bringing this to our attention.","Gracias por hacérnoslo saber."],["Política","According to our return policy, items can be returned within 30 days.","Según nuestra política de devoluciones, los artículos se pueden devolver dentro de 30 días."],["Lenguaje positivo","What I can do is…","Lo que sí puedo hacer es…"],["Lenguaje positivo","The best option for you would be…","La mejor opción para usted sería…"],["Límite suave","Unfortunately, I'm not able to… but I can…","Desafortunadamente no puedo…, pero sí puedo…"]],"nota":"Las cifras de ejemplo (como 30 días) son inventadas: en tu trabajo usa siempre la política real de la empresa."},{"tipo":"comparar","titulo":"Negativo contra positivo","malTitulo":"Lenguaje negativo","mal":"<i>That's not my department.</i><br><i>We can't do that. It's the policy.</i><br><i>The system made a mistake, not me.</i><br><i>You should have read the terms.</i>","bienTitulo":"Lenguaje positivo","bien":"<i>Let me connect you with the team that can help.</i><br><i>What I can do is offer you store credit.</i><br><i>I apologize for the error. Let me correct it.</i><br><i>Let me explain how it works, so it's clear.</i>"},{"tipo":"dialogo","titulo":"Diálogo — Una devolución fuera de plazo","lineas":[{"quien":"Customer","en":"I want to return these headphones. I bought them 45 days ago, and they stopped working.","es":"Quiero devolver estos audífonos. Los compré hace 45 días y dejaron de funcionar."},{"quien":"Agent","en":"I'm very sorry to hear that. According to our return policy, returns are accepted within 30 days.","es":"Lamento mucho escuchar eso. Según nuestra política de devoluciones, se aceptan devoluciones dentro de 30 días."},{"quien":"Customer","en":"So you can't do anything?","es":"¿Entonces no puede hacer nada?"},{"quien":"Agent","en":"What I can do is check your warranty. These headphones have a one-year warranty, so we can send you a replacement.","es":"Lo que sí puedo hacer es revisar su garantía. Estos audífonos tienen un año de garantía, así que le podemos enviar un reemplazo."},{"quien":"Customer","en":"Oh, that works. Thank you.","es":"Ah, eso me sirve. Gracias."}]},{"tipo":"practica","rotulo":"¿Cuál suena más profesional?","preguntas":[{"p":"El cliente reporta un error en su cuenta.","ops":["The system made a mistake, not me.","I apologize for the error. Let me correct it.","That happens a lot."],"correcta":1},{"p":"No puedes hacer un reembolso en efectivo.","ops":["No cash. Policy.","You can't have cash, sorry.","Unfortunately, I'm not able to refund in cash, but I can refund it to your card."],"correcta":2},{"p":"El tema es de otra área.","ops":["Let me connect you with the team that can help.","That's not my department.","Call another number."],"correcta":0},{"p":"«Lo que sí puedo hacer es…» se dice…","ops":["What I can do is…","The thing I do can is…","I can do what is…"],"correcta":0},{"p":"«Gracias por hacérnoslo saber» se dice…","ops":["Thanks for saying me.","Thank you for bringing this to our attention.","Thank you for your attention please."],"correcta":1}]},{"tipo":"relacionar","rotulo":"Relaciona la palabra con su significado","voz":true,"pares":[["policy","política o regla de la empresa"],["warranty","garantía"],["replacement","reemplazo"],["store credit","saldo a favor en la tienda"],["inconvenience","inconveniente, molestia"],["receipt","recibo o ticket de compra"]]},{"tipo":"ordenar","rotulo":"Arma la frase en lenguaje positivo","voz":true,"items":[{"frase":"I'm very sorry for the inconvenience","es":"Lamento mucho el inconveniente"},{"frase":"What I can do is send you a replacement","es":"Lo que sí puedo hacer es enviarle un reemplazo"},{"frase":"I apologize for the delay with your order","es":"Me disculpo por el retraso con su pedido"}]},{"tipo":"pronunciar","rotulo":"Practica en voz alta","frases":[{"en":"I'm very sorry for the inconvenience.","pron":"aim véri sóri for di inconvíniens","es":"Lamento mucho el inconveniente."},{"en":"What I can do is offer you a replacement.","es":"Lo que sí puedo hacer es ofrecerle un reemplazo."},{"en":"According to our return policy…","pron":"acórding tu áuer ritérn pólisi","es":"Según nuestra política de devoluciones…"}]},{"tipo":"clave","items":["Discúlpate en nombre de la empresa sin culpar al sistema, a otra área ni al cliente.","Explica la política y enseguida di lo que sí puedes hacer: <i>What I can do is…</i>","Usa siempre las políticas reales de tu empresa, no las del ejemplo."]}],"c-ingles-servicio-m2-l3":[{"tipo":"texto","texto":"Ofrecer una solución en inglés tiene tres claves: <b>1)</b> si puedes, da <b>dos opciones</b> para que el cliente elija y sienta control; <b>2)</b> di <b>qué va a pasar y cuándo</b>; <b>3)</b> promete solo lo que <b>sí</b> vas a cumplir. Y si el caso rebasa tus permisos o el cliente lo pide, <b>escalas</b> (<i>escalate</i>) a un supervisor, siguiendo el procedimiento de tu empresa."},{"tipo":"tabla","titulo":"Soluciones y escalamiento","voz":true,"colVoz":1,"encabezados":["Para…","Frase","Español"],"filas":[["Dar opciones","I can offer you two options.","Le puedo ofrecer dos opciones."],["Opción 1","I can send a new one by express shipping.","Le puedo enviar uno nuevo por envío exprés."],["Opción 2","Or I can issue a full refund.","O le puedo hacer un reembolso completo."],["Que elija","Which option would you prefer?","¿Qué opción prefiere?"],["Plazo","You'll receive a confirmation email within 24 hours.","Recibirá un correo de confirmación en menos de 24 horas."],["Escalar","I'm going to escalate this to my supervisor.","Voy a escalar esto con mi supervisor."],["Cliente lo pide","Of course. Let me get a supervisor for you.","Claro. Permítame comunicarle con un supervisor."],["Seguimiento","Your case number is 4-8-2-7. Please keep it for reference.","Su número de caso es 4827. Guárdelo como referencia."]]},{"tipo":"pasos","rotulo":"Cómo escalar bien una llamada","pasos":["<b>Explica al cliente</b> qué vas a hacer y por qué: <i>My supervisor has more options to help you with this.</i>","<b>Pide permiso para la espera</b> y di un tiempo aproximado: <i>May I place you on hold for about three minutes?</i>","<b>Resume el caso</b> a tu supervisor: nombre, problema, lo que ya intentaste y lo que pide el cliente.","<b>Presenta</b> al supervisor si es transferencia cálida: <i>Ms. Lopez, I have Mr. Green on the line. He was charged twice…</i>","<b>Registra</b> el caso en el sistema y da el número de caso al cliente, si tu procedimiento lo indica."]},{"tipo":"dialogo","titulo":"Diálogo — Dos opciones y un plazo","lineas":[{"quien":"Agent","en":"I can see your blender arrived damaged. I apologize for that. I can offer you two options.","es":"Veo que su licuadora llegó dañada. Me disculpo por eso. Le puedo ofrecer dos opciones."},{"quien":"Agent","en":"I can send you a new one by express shipping, or I can issue a full refund. Which option would you prefer?","es":"Le puedo enviar una nueva por envío exprés o le puedo hacer un reembolso completo. ¿Qué opción prefiere?"},{"quien":"Customer","en":"I'd prefer a new one. When will it arrive?","es":"Prefiero una nueva. ¿Cuándo llegaría?"},{"quien":"Agent","en":"It should arrive in two to three business days. You'll receive a tracking number by email today.","es":"Debe llegar en dos a tres días hábiles. Hoy recibirá un número de rastreo por correo."},{"quien":"Customer","en":"Perfect, thanks.","es":"Perfecto, gracias."}]},{"tipo":"practica","rotulo":"Elige la mejor opción","preguntas":[{"p":"¿Qué frase le da control al cliente?","ops":["Which option would you prefer?","I decide the solution.","Take the refund."],"correcta":0},{"p":"No sabes exactamente cuándo llega el reemplazo. ¿Qué dices?","ops":["It will arrive tomorrow, 100%.","It should arrive in two to three business days.","I have no idea."],"correcta":1,"explica":"<i>It should…</i> da un plazo realista sin prometer de más."},{"p":"El cliente pide hablar con un supervisor. ¿Qué respondes?","ops":["No, you talk to me.","Supervisors are busy.","Of course. Let me get a supervisor for you."],"correcta":2},{"p":"«Voy a escalar esto con mi supervisor» se dice…","ops":["I'm going to climb this to my boss.","I'm going to escalate this to my supervisor.","I will up this for supervisor."],"correcta":1},{"p":"Al escalar, ¿qué le dices a tu supervisor?","ops":["Solo el nombre del cliente","Nada: que el cliente le vuelva a explicar","Nombre, problema, lo que intentaste y lo que pide el cliente"],"correcta":2}]},{"tipo":"completar","rotulo":"Completa la solución","voz":true,"items":[{"frase":"I can ___ you two options.","resp":["offer","give"],"es":"Le puedo ofrecer dos opciones."},{"frase":"Which option would you ___?","resp":["prefer","like"],"es":"¿Qué opción prefiere?"},{"frase":"I can issue a full ___.","resp":["refund"],"es":"Le puedo hacer un reembolso completo."},{"frase":"You'll receive a confirmation email ___ 24 hours.","resp":["within"],"es":"Recibirá un correo de confirmación en menos de 24 horas."},{"frase":"Your case ___ is 4-8-2-7.","resp":["number"],"es":"Su número de caso es 4827."}]},{"tipo":"clave","items":["Da dos opciones, deja elegir y di qué pasará y cuándo (<i>It should arrive in…</i>).","Promete solo lo que puedes cumplir; usa <i>should</i> para plazos aproximados.","Escala explicando el motivo, resume el caso al supervisor y da el número de caso."]}],"c-ingles-servicio-m2-l4":[{"tipo":"texto","texto":"Un cliente molesto casi nunca está enojado <b>contigo</b>: está enojado con la situación. Tu objetivo es <b>bajar la tensión</b> (<i>de-escalate</i>): voz tranquila, volumen bajo, ritmo más lento y frases que reconocen su molestia. Hay frases que parecen inocentes pero <b>encienden</b> más la llamada, como <i>Calm down</i> o <i>You need to…</i>. Y si hay insultos, tienes derecho a poner un límite siguiendo el procedimiento de tu empresa."},{"tipo":"comparar","titulo":"Frases a evitar contra frases que calman","malTitulo":"Suben la tensión","mal":"<i>Calm down.</i><br><i>You need to…</i><br><i>That's impossible.</i><br><i>I already told you.</i><br><i>It's not my fault.</i><br><i>Honestly, I don't know.</i>","bienTitulo":"Bajan la tensión","bien":"<i>I understand this is upsetting.</i><br><i>What I'd recommend is…</i><br><i>Let me see what options we have.</i><br><i>Let me explain it another way.</i><br><i>I'm sorry this happened. Let's fix it.</i><br><i>Let me find out for you.</i>"},{"tipo":"tabla","titulo":"Frases para momentos difíciles","voz":true,"colVoz":1,"encabezados":["Situación","Frase","Español"],"filas":[["El cliente grita","I can hear how upset you are, and I want to help.","Escucho lo molesto que está y quiero ayudarle."],["Te interrumpe","Please, go ahead. I'm listening.","Adelante, por favor. Le escucho."],["Pide lo imposible","I wish I could do that. Here's what I can do.","Ojalá pudiera hacerlo. Esto es lo que sí puedo hacer."],["No sabes algo","That's a great question. Let me find out for you.","Buena pregunta. Déjeme averiguarlo."],["Primer aviso por insultos","I want to help you, but I need us to keep this respectful.","Quiero ayudarle, pero necesito que mantengamos el respeto."],["Si sigue","If the language continues, I'll have to end the call.","Si continúa ese lenguaje, tendré que terminar la llamada."]],"nota":"Cada empresa tiene su propio procedimiento para llamadas con insultos. Aprende el tuyo y avisa a tu supervisor."},{"tipo":"dialogo","titulo":"Diálogo — Tercera llamada por el mismo problema","lineas":[{"quien":"Customer","en":"This is the third time I'm calling! Nobody fixes my internet. This is ridiculous!","es":"¡Es la tercera vez que llamo! Nadie arregla mi internet. ¡Esto es ridículo!"},{"quien":"Agent","en":"I can hear how upset you are, and I completely understand. Having to call three times is not OK. I'm sorry this happened.","es":"Escucho lo molesto que está y lo entiendo completamente. Tener que llamar tres veces no está bien. Lamento que haya pasado."},{"quien":"Customer","en":"I just want it to work!","es":"¡Solo quiero que funcione!"},{"quien":"Agent","en":"Of course. I'm going to take ownership of this case. Let me see what options we have.","es":"Claro. Voy a hacerme cargo de este caso. Déjeme ver qué opciones tenemos."},{"quien":"Agent","en":"I've scheduled a technician for tomorrow between 9 and 12, and I'll call you tomorrow afternoon to make sure it's fixed.","es":"Le agendé un técnico para mañana entre 9 y 12, y le llamaré mañana en la tarde para asegurarme de que quedó resuelto."},{"quien":"Customer","en":"OK. Thank you. Sorry for yelling.","es":"Está bien. Gracias. Perdón por gritar."}]},{"tipo":"practica","rotulo":"¿Qué frase baja la tensión?","preguntas":[{"p":"El cliente está gritando.","ops":["Calm down, sir.","Don't shout at me.","I can hear how upset you are, and I want to help."],"correcta":2},{"p":"Te pide algo que no puedes hacer.","ops":["I wish I could do that. Here's what I can do.","That's impossible.","No way."],"correcta":0},{"p":"Ya le explicaste y no entendió.","ops":["I already told you.","Let me explain it another way.","Listen carefully this time."],"correcta":1},{"p":"No sabes la respuesta.","ops":["Honestly, I don't know.","Nobody knows that.","Let me find out for you."],"correcta":2},{"p":"<i>I'm going to take ownership of this case</i> significa…","ops":["Voy a cerrar este caso","Voy a hacerme cargo de este caso","Voy a comprar este caso"],"correcta":1}]},{"tipo":"ordenar","rotulo":"Arma las frases que calman","voz":true,"items":[{"frase":"Please go ahead, I am listening","es":"Adelante, por favor, le escucho"},{"frase":"I'm sorry this happened. Let's fix it","es":"Lamento que haya pasado. Resolvámoslo"},{"frase":"Let me see what options we have","es":"Déjeme ver qué opciones tenemos"}]},{"tipo":"pronunciar","rotulo":"Practica con voz baja y lenta","frases":[{"en":"I can hear how upset you are, and I want to help.","pron":"ai can jíer jáu apsét iu ar and ai uant tu jelp","es":"Escucho lo molesto que está y quiero ayudarle."},{"en":"I wish I could do that. Here's what I can do.","es":"Ojalá pudiera hacerlo. Esto es lo que sí puedo hacer."},{"en":"I need us to keep this respectful.","es":"Necesito que mantengamos el respeto."}]},{"tipo":"reflexion","rotulo":"Tu guion para la llamada difícil","pregunta":"Piensa en una queja típica de tu trabajo (o del trabajo que quieres). Escribe en inglés cómo responderías: una señal de escucha, una paráfrasis, una frase de empatía, una disculpa, dos opciones y un cierre. Luego léelo en voz alta con voz tranquila.","ayuda":"I see… So, if I understand correctly… I understand how frustrating… I'm sorry… I can offer you two options… Is there anything else…?"},{"tipo":"clave","items":["El cliente está molesto con la situación, no contigo: voz baja, ritmo lento y empatía.","Evita <i>Calm down, It's not my fault, I already told you</i>; usa <i>Let me see what options we have.</i>","Ante insultos, pon un límite respetuoso y sigue el procedimiento de tu empresa."]}],"c-ingles-servicio-m3-l1":[{"tipo":"texto","texto":"El error más común al vender por teléfono es <b>recomendar antes de preguntar</b>. Un buen agente primero entiende: ¿para qué lo quiere?, ¿cuántas personas lo usarán?, ¿qué le molesta de lo que tiene ahora? Para eso combinas dos tipos de preguntas: las <b>abiertas</b> (<i>What, How, Why, Tell me…</i>), que hacen hablar al cliente, y las <b>cerradas</b> (<i>Do you…? Is it…? Would you…?</i>), que confirman un dato con sí o no."},{"tipo":"tabla","titulo":"Preguntas que descubren necesidades","voz":true,"colVoz":1,"encabezados":["Tipo","Pregunta","Español"],"filas":[["Abierta","What will you mainly use it for?","¿Para qué lo va a usar principalmente?"],["Abierta","How many people will be using the plan?","¿Cuántas personas usarán el plan?"],["Abierta","What do you like or dislike about your current plan?","¿Qué le gusta o no de su plan actual?"],["Abierta","Could you tell me a little more about that?","¿Me podría contar un poco más sobre eso?"],["Cerrada","Do you travel outside the U.S. often?","¿Viaja seguido fuera de EE. UU.?"],["Cerrada","Is price your main concern?","¿El precio es lo que más le importa?"],["Confirmar","So you need something reliable for working from home. Is that right?","Entonces necesita algo confiable para trabajar desde casa. ¿Es correcto?"]]},{"tipo":"dialogo","titulo":"Diálogo — Un cliente que quiere cambiar de plan","lineas":[{"quien":"Customer","en":"I'd like to change my internet plan. It's too slow.","es":"Quiero cambiar mi plan de internet. Está muy lento."},{"quien":"Agent","en":"I can help you with that. What do you mainly use your internet for?","es":"Con gusto le ayudo. ¿Para qué usa principalmente su internet?"},{"quien":"Customer","en":"I work from home, and my kids play online games.","es":"Trabajo desde casa y mis hijos juegan en línea."},{"quien":"Agent","en":"I see. How many devices are connected at the same time, more or less?","es":"Ya veo. ¿Cuántos dispositivos se conectan al mismo tiempo, más o menos?"},{"quien":"Customer","en":"Maybe six or seven in the evening.","es":"Tal vez seis o siete en la tarde-noche."},{"quien":"Agent","en":"And is price your main concern, or is speed more important?","es":"¿Y lo que más le importa es el precio o la velocidad?"},{"quien":"Customer","en":"Speed, definitely.","es":"La velocidad, definitivamente."}]},{"tipo":"practica","rotulo":"¿Abierta o cerrada?","preguntas":[{"p":"<i>What will you mainly use it for?</i>","ops":["De confirmación","Retórica","Cerrada","Abierta"],"correcta":3,"explica":"Empieza con <i>What</i> y no se contesta con sí o no: es una pregunta abierta que invita al cliente a explicar."},{"p":"<i>Do you have Wi-Fi at home?</i>","ops":["Cerrada","Abierta","De opción múltiple","Retórica"],"correcta":0,"explica":"Empieza con <i>Do</i> y se contesta con sí o no: es una pregunta cerrada, útil para confirmar datos."},{"p":"Quieres que el cliente te cuente más. ¿Qué dices?","ops":["Yes or no?","Could you tell me a little more about that?","OK, next question."],"correcta":1},{"p":"«¿Cuántas personas usarán el plan?» se dice…","ops":["How many people will be using the plan?","How much people use plan?","How many people is using the plan?"],"correcta":0},{"p":"¿Cuándo conviene recomendar un plan?","ops":["En cuanto el cliente saluda","Nunca: solo contesta preguntas","Después de entender qué necesita y confirmarlo"],"correcta":2}]},{"tipo":"completar","rotulo":"Completa las preguntas","voz":true,"items":[{"frase":"What will you ___ use it for?","resp":["mainly"],"es":"¿Para qué lo va a usar principalmente?"},{"frase":"How ___ people will be using the plan?","resp":["many"],"es":"¿Cuántas personas usarán el plan?"},{"frase":"Could you tell me a little ___ about that?","resp":["more"],"es":"¿Me podría contar un poco más sobre eso?"},{"frase":"___ price your main concern?","resp":["Is"],"es":"¿El precio es lo que más le importa?"},{"frase":"What do you like or dislike about your ___ plan?","resp":["current"],"es":"¿Qué le gusta o no de su plan actual?"}]},{"tipo":"pronunciar","rotulo":"Pregunta con entonación","frases":[{"en":"What will you mainly use it for?","pron":"uát uil iu méinli iús it for","es":"¿Para qué lo va a usar principalmente?"},{"en":"Could you tell me a little more about that?","pron":"kud iu tel mi a lítel mor abáut dat","es":"¿Me podría contar un poco más sobre eso?"},{"en":"Do you travel outside the U.S. often?","es":"¿Viaja seguido fuera de EE. UU.?"}]},{"tipo":"clave","items":["Primero pregunta, después recomienda.","Preguntas abiertas (<i>What, How, Tell me…</i>) para descubrir; cerradas (<i>Do you…? Is it…?</i>) para confirmar.","Resume la necesidad antes de ofrecer: <i>So you need… Is that right?</i>"]}],"c-ingles-servicio-m3-l2":[{"tipo":"texto","texto":"Al describir un producto, el cliente no compra «características» sino <b>beneficios</b>: no le importa tanto «500 megas» como «puedes trabajar en videollamada mientras tus hijos juegan sin que se trabe». El <b>upselling</b> es ofrecer una opción mejor o un complemento, y funciona cuando está <b>conectado con lo que el cliente dijo</b>. Si el cliente dice que no, se acepta con amabilidad: presionar arruina la confianza y, en muchas empresas, las ventas engañosas o forzadas están prohibidas."},{"tipo":"vocabulario","rotulo":"Vocabulario de productos y planes","palabras":[{"en":"feature","es":"característica","ej":"This plan includes a great feature: unlimited data."},{"en":"benefit","es":"beneficio","ej":"The main benefit is that you never pay extra."},{"en":"monthly fee","es":"cuota mensual","ej":"The monthly fee is $45."},{"en":"upgrade","es":"mejora, subir de plan","ej":"Would you like to upgrade your plan?"},{"en":"add-on","es":"complemento","ej":"You can add international calls as an add-on."},{"en":"contract","es":"contrato, plazo forzoso","ej":"There is no contract. You can cancel anytime."},{"en":"discount","es":"descuento","ej":"You get a 10% discount for the first three months."},{"en":"deal","es":"oferta, promoción","ej":"That's a great deal for a family of four."}]},{"tipo":"tabla","titulo":"Del «tiene» al «le sirve para»","voz":true,"colVoz":1,"encabezados":["Característica","Beneficio para el cliente","Español"],"filas":[["500 Mbps speed","You can work on video calls while your kids play online.","Puede trabajar en videollamadas mientras sus hijos juegan en línea."],["No contract","You can cancel anytime without a penalty.","Puede cancelar cuando quiera sin penalización."],["24/7 support","If anything goes wrong, you can call us any time.","Si algo falla, nos puede llamar a cualquier hora."],["Extended warranty","If it breaks, you won't pay for repairs for two years.","Si se descompone, no pagará reparaciones durante dos años."]],"nota":"Datos inventados para practicar: en tu trabajo usa siempre precios y condiciones reales, y no prometas beneficios que el producto no tiene."},{"tipo":"dialogo","titulo":"Diálogo — Una mejora cortés","lineas":[{"quien":"Agent","en":"Based on what you told me, I would recommend our 500 Mbps plan. You can work on video calls while your kids play online, with no interruptions.","es":"Por lo que me dice, le recomendaría nuestro plan de 500 Mbps. Puede trabajar en videollamadas mientras sus hijos juegan en línea, sin interrupciones."},{"quien":"Customer","en":"How much is it?","es":"¿Cuánto cuesta?"},{"quien":"Agent","en":"It's $65 a month, which is $15 more than your current plan. There's no contract, so you can change it anytime.","es":"Son 65 dólares al mes, 15 más que su plan actual. No hay plazo forzoso, así que lo puede cambiar cuando quiera."},{"quien":"Customer","en":"OK, that sounds good.","es":"Ok, suena bien."},{"quien":"Agent","en":"Great. Since you work from home, would you also be interested in our tech support add-on? It's $5 a month.","es":"Excelente. Como trabaja desde casa, ¿le interesaría también nuestro complemento de soporte técnico? Cuesta 5 dólares al mes."},{"quien":"Customer","en":"No, thanks. Just the plan.","es":"No, gracias. Solo el plan."},{"quien":"Agent","en":"No problem at all. Let me set up your new plan.","es":"No hay ningún problema. Déjeme activar su nuevo plan."}]},{"tipo":"comparar","titulo":"Upselling con presión contra upselling cortés","malTitulo":"Con presión","mal":"<i>You really need this. Everybody buys it.</i><br><i>Are you sure? It's only today. Last chance!</i><br>Insistir tres veces después de un «no».","bienTitulo":"Cortés","bien":"<i>Since you mentioned…, would you be interested in…?</i><br><i>It's completely optional.</i><br><i>No problem at all.</i> (y sigues con la llamada)"},{"tipo":"practica","rotulo":"Elige la mejor opción","preguntas":[{"p":"¿Cuál frase describe un beneficio?","ops":["It has 500 Mbps.","It has a new chip.","You can watch movies without interruptions."],"correcta":2},{"p":"¿Cuál es un upselling cortés?","ops":["You need this, trust me.","Since you travel a lot, would you be interested in our international add-on?","Buy it now or lose it forever."],"correcta":1},{"p":"El cliente dice <i>No, thanks</i>. ¿Qué respondes?","ops":["Are you sure? Think about it.","No problem at all.","That's a mistake."],"correcta":1},{"p":"<i>There's no contract</i> significa…","ops":["No hay plazo forzoso","No hay contrato de trabajo","No hay descuento"],"correcta":0},{"p":"«Por lo que me dice, le recomendaría…» se dice…","ops":["For what you say me, I recommend you…","Based on what you told me, I would recommend…","About your words, I recommend…"],"correcta":1}]},{"tipo":"relacionar","rotulo":"Relaciona","voz":true,"pares":[["upgrade","subir de plan"],["add-on","complemento"],["monthly fee","cuota mensual"],["feature","característica"],["cancel anytime","cancelar cuando quiera"],["penalty","penalización"]]},{"tipo":"clave","items":["Describe beneficios, no solo características: <i>You can… / You won't have to…</i>","Conecta la mejora con lo que dijo el cliente: <i>Since you mentioned…, would you be interested in…?</i>","Acepta el «no» con <i>No problem at all</i> y nunca prometas lo que el producto no tiene."]}],"c-ingles-servicio-m3-l3":[{"tipo":"texto","texto":"Las llamadas de dinero y paquetes son de las más frecuentes y las que más ansiedad generan. Tres reglas: <b>1)</b> confirma siempre el <b>monto</b> y la <b>fecha</b> repitiéndolos; <b>2)</b> di los plazos de reembolso y envío tal como los marca tu empresa (en <b>días hábiles</b>, <i>business days</i>, si así se manejan); <b>3)</b> no leas en voz alta datos completos de tarjetas y sigue las reglas de seguridad de pagos de tu empresa."},{"tipo":"vocabulario","rotulo":"Vocabulario de pagos y envíos","palabras":[{"en":"charge","es":"cargo","ej":"I see a charge of $29.99 on June 5th."},{"en":"refund","es":"reembolso","ej":"Your refund has been processed."},{"en":"billing cycle","es":"periodo de facturación","ej":"The change will apply in your next billing cycle."},{"en":"due date","es":"fecha límite de pago","ej":"Your due date is the 15th of each month."},{"en":"pending","es":"pendiente","ej":"The payment is still pending."},{"en":"tracking number","es":"número de rastreo","ej":"I'll email you the tracking number."},{"en":"shipped","es":"enviado","ej":"Your order shipped yesterday."},{"en":"out for delivery","es":"en ruta de entrega","ej":"Your package is out for delivery today."}]},{"tipo":"tabla","titulo":"Frases para dinero y paquetes","voz":true,"colVoz":1,"encabezados":["Situación","Frase","Español"],"filas":[["Explicar un cargo","This charge is for your monthly subscription.","Este cargo es por su suscripción mensual."],["Confirmar monto","Just to confirm, that's a refund of $42.50 to your Visa ending in 1234.","Para confirmar, es un reembolso de 42.50 a su Visa con terminación 1234."],["Plazo de reembolso","It may take five to seven business days to appear on your statement.","Puede tardar de cinco a siete días hábiles en aparecer en su estado de cuenta."],["Pago rechazado","It looks like the payment was declined.","Parece que el pago fue rechazado."],["Estado del envío","Your order has shipped and is in transit.","Su pedido fue enviado y está en tránsito."],["Entrega estimada","The estimated delivery date is Thursday.","La fecha estimada de entrega es el jueves."]],"nota":"Montos, tarjetas y plazos del ejemplo son inventados. Los reales dependen de tu empresa y del banco del cliente."},{"tipo":"dialogo","titulo":"Diálogo — ¿Dónde está mi reembolso?","lineas":[{"quien":"Customer","en":"I returned a jacket two weeks ago, and I still don't see my refund.","es":"Devolví una chamarra hace dos semanas y todavía no veo mi reembolso."},{"quien":"Agent","en":"Let me check that for you. I can see we received the jacket on May 20th, and the refund was processed on May 22nd.","es":"Déjeme revisarlo. Veo que recibimos la chamarra el 20 de mayo y el reembolso se procesó el 22 de mayo."},{"quien":"Customer","en":"So where is it?","es":"¿Y entonces dónde está?"},{"quien":"Agent","en":"Refunds can take five to seven business days to appear on your statement, depending on your bank. It should appear by the end of this week.","es":"Los reembolsos pueden tardar de cinco a siete días hábiles en aparecer en su estado de cuenta, según su banco. Debe aparecer a más tardar a fin de semana."},{"quien":"Agent","en":"Just to confirm, it's $89.00 to your card ending in 4471.","es":"Para confirmar, son 89 dólares a su tarjeta con terminación 4471."},{"quien":"Customer","en":"OK, that's clear. Thanks.","es":"Ok, queda claro. Gracias."}]},{"tipo":"practica","rotulo":"¿Qué significa?","preguntas":[{"p":"<i>Your package is out for delivery.</i>","ops":["Su paquete se perdió","Su paquete está en ruta para entregarse hoy","Su paquete regresó al almacén"],"correcta":1},{"p":"<i>The payment was declined.</i>","ops":["El pago fue rechazado","El pago fue aceptado","El pago está duplicado"],"correcta":0},{"p":"<i>business days</i> son…","ops":["días de negocios del cliente","días festivos","días hábiles (normalmente de lunes a viernes)"],"correcta":2},{"p":"¿Cómo confirmas un reembolso?","ops":["OK, done.","Just to confirm, that's a refund of $42.50 to your card ending in 1234.","Money goes back, bye."],"correcta":1},{"p":"«Su tarjeta con terminación 1234» se dice…","ops":["your card finishing 1234","your card with termination 1234","your card ending in 1234"],"correcta":2}]},{"tipo":"completar","rotulo":"Completa","voz":true,"items":[{"frase":"Your refund has been ___.","resp":["processed","issued"],"es":"Su reembolso ya fue procesado."},{"frase":"It may take five to seven ___ days.","resp":["business"],"es":"Puede tardar de cinco a siete días hábiles."},{"frase":"I'll email you the ___ number.","resp":["tracking"],"es":"Le mando por correo el número de rastreo."},{"frase":"The payment is still ___.","resp":["pending"],"es":"El pago sigue pendiente."},{"frase":"The estimated ___ date is Thursday.","resp":["delivery"],"es":"La fecha estimada de entrega es el jueves."}]},{"tipo":"pronunciar","rotulo":"Practica en voz alta","frases":[{"en":"Just to confirm, that's a refund of forty-two fifty.","pron":"yast tu confírm dats a rífand ov fórti tu fífti","es":"Para confirmar, es un reembolso de 42.50."},{"en":"Your order has shipped and is in transit.","es":"Su pedido fue enviado y está en tránsito."},{"en":"It may take five to seven business days.","pron":"it méi téik fáiv tu séven bísnes déis","es":"Puede tardar de cinco a siete días hábiles."}]},{"tipo":"clave","items":["Confirma monto, fecha y medio de pago: <i>Just to confirm, that's… to your card ending in…</i>","Da plazos realistas en <i>business days</i>, según la política real de tu empresa.","Envíos: <i>shipped → in transit → out for delivery → delivered</i>."]}],"c-ingles-servicio-m3-l4":[{"tipo":"texto","texto":"Muchos anuncios piden «acento neutro». Lo que un cliente realmente necesita es <b>entenderte a la primera</b>. No tienes que sonar como alguien de Texas ni esconder que eres de México: un acento se nota y está bien. Lo que sí importa es la <b>claridad</b>: acentuar la sílaba correcta, no comerte los finales de palabra, <b>bajar la velocidad</b> cuando das datos y usar un tono cálido. Recuerda que por teléfono no se ve tu cara: <b>la sonrisa se escucha</b>."},{"tipo":"lista","items":["<b>Velocidad:</b> más lento para números, nombres y pasos a seguir; normal para la conversación.","<b>Finales de palabra:</b> pronuncia la última consonante: <i>help<b>ed</b>, ask<b>ed</b>, work<b>s</b>, change<b>d</b></i>.","<b>Sílaba fuerte:</b> <i>de<b>VEL</b>op, <b>COM</b>fortable, ac<b>COUNT</b>, <b>SCHED</b>ule</i>. Un acento en la sílaba equivocada confunde más que el acento regional.","<b>Entonación:</b> sube al final en preguntas de sí o no (<i>Is that correct?</i> ↗) y baja en preguntas con <i>What, How</i> (↘).","<b>Sonidos difíciles:</b> <i>th</i> (<i>thank, three</i>), <i>v</i> contra <i>b</i> (<i>very, berry</i>), y la vocal corta de <i>ship</i> contra la larga de <i>sheep</i>."]},{"tipo":"tabla","titulo":"Enlaces de palabras (linking)","voz":true,"colVoz":1,"encabezados":["Se escribe","Suena como","Regla"],"filas":[["Can I help you?","ca-nai-help-you","Consonante + vocal se unen"],["Let me check it out.","let-me-che-ki-tout","Consonante + vocal se unen"],["Thank you for holding.","thank-yuh-fer-holding","Palabras pequeñas se reducen (for → fer)"],["I'll send it to you.","ail-sen-di-tu-you","La d se enlaza con la vocal que sigue"],["What do you need?","wha-dyu-need","Reducción informal muy común"]],"nota":"Entender los enlaces te ayuda sobre todo a <b>escuchar</b> a clientes nativos que hablan rápido. Al hablar, úsalos con naturalidad, pero sin sacrificar claridad."},{"tipo":"escuchar","rotulo":"Escucha cómo se enlazan las palabras","frases":[{"en":"Can I help you with anything else?","pron":"ca-nai jel-piu uí-zé-ni-zing els","es":"¿Le ayudo con algo más?"},{"en":"Let me check it out for you.","pron":"let mi ché-ki-táut for iu","es":"Déjeme revisarlo por usted."},{"en":"I'll send it to you right away.","es":"Se lo envío de inmediato."},{"en":"Thank you for holding.","pron":"zán-kiu fer jóul-ding","es":"Gracias por esperar."}]},{"tipo":"practica","rotulo":"¿Qué ayuda más a que te entiendan?","preguntas":[{"p":"Vas a dar un número de caso de 10 dígitos.","ops":["Decirlo rápido para no quitar tiempo","Decirlo más lento, en grupos, y pedir que lo repitan","Decirlo una sola vez sin pausas"],"correcta":1},{"p":"¿Dónde va la sílaba fuerte en <i>account</i>?","ops":["ac<b>COUNT</b>","Igual en las dos sílabas","<b>AC</b>count","Depende de si es verbo o sustantivo"],"correcta":0,"explica":"Se dice a-<b>COUNT</b>: la fuerza va en la segunda sílaba, sea verbo o sustantivo."},{"p":"Sobre tu acento mexicano…","ops":["Debes eliminarlo por completo","No importa nada cómo pronuncies","Puedes conservarlo; lo importante es que te entiendan a la primera"],"correcta":2},{"p":"<i>Is that correct?</i> Al final, la voz…","ops":["sube ↗","baja ↘","se queda igual"],"correcta":0,"explica":"En preguntas de sí o no, la entonación suele subir al final."},{"p":"¿Por qué conviene sonreír al hablar por teléfono?","ops":["Porque el cliente te ve por video","Porque la sonrisa cambia el tono de voz y se escucha más cálida","No sirve de nada"],"correcta":1}]},{"tipo":"pronunciar","rotulo":"Practica los sonidos difíciles","frases":[{"en":"Thank you. Three, thirteen, thirty.","pron":"zank iu. zri, zertín, zérti","es":"Gracias. Tres, trece, treinta."},{"en":"Very good. The berry is very sweet.","pron":"véri gud. de béri is véri suít","es":"Muy bien. La mora está muy dulce."},{"en":"The sheep is on the ship.","es":"La oveja está en el barco."},{"en":"I helped. I asked. It changed.","pron":"ai jelpt. ai askt. it chéinshd","es":"Ayudé. Pregunté. Cambió."},{"en":"Can I help you with anything else?","es":"¿Le ayudo con algo más?"}]},{"tipo":"reflexion","rotulo":"Grábate","pregunta":"Grábate con el celular diciendo tu saludo de guion, un número de teléfono de EE. UU., una frase de empatía y tu cierre. Escúchate: ¿se entiende tu nombre?, ¿los números van con pausas?, ¿se nota la sonrisa?, ¿pronunciaste los finales de palabra? Anota dos cosas que vas a mejorar y vuelve a grabarte.","ayuda":"Thank you for calling… My name is… Five one two, five five five… I understand how frustrating… Have a great day!"},{"tipo":"clave","items":["Claridad sobre «acento neutro»: no borras tu identidad, te aseguras de que te entiendan.","Más lento para datos; pronuncia los finales y la sílaba fuerte correcta.","Los enlaces (<i>Can I → ca-nai</i>) te ayudan sobre todo a entender a nativos rápidos."]}],"c-ingles-servicio-m4-l1":[{"tipo":"texto","texto":"En Cancún, la Riviera Maya, Los Cabos, Puerto Vallarta o San Miguel de Allende, la recepción del hotel es la primera cara de México para muchos visitantes. Cara a cara, además de las frases, cuentan el <b>contacto visual</b>, la sonrisa y la postura. El check-in tiene una secuencia casi fija: <b>bienvenida → nombre de la reservación → identificación y forma de pago → datos de la estancia → llave e indicaciones</b>."},{"tipo":"tabla","titulo":"Frases de recepción","voz":true,"colVoz":1,"encabezados":["Momento","Frase","Español"],"filas":[["Bienvenida","Welcome to Hotel Mar Azul! Are you checking in?","¡Bienvenidos al Hotel Mar Azul! ¿Van a registrarse?"],["Reservación","May I have the name on the reservation, please?","¿Me da el nombre de la reservación, por favor?"],["Identificación","May I see your passport and a credit card for incidentals?","¿Me permite su pasaporte y una tarjeta de crédito para gastos adicionales?"],["Estancia","You're staying with us for four nights, until Saturday. Is that correct?","Se hospeda con nosotros cuatro noches, hasta el sábado. ¿Es correcto?"],["Llave","Here are your key cards. Your room is on the fifth floor.","Aquí están sus tarjetas-llave. Su habitación está en el quinto piso."],["Indicaciones","Breakfast is served from 7 to 11 in the main restaurant.","El desayuno se sirve de 7 a 11 en el restaurante principal."],["Check-out","How was your stay? Here is your final bill.","¿Qué tal su estancia? Aquí está su cuenta final."]],"nota":"Horarios, pisos y depósitos del ejemplo son inventados: usa siempre los de tu hotel."},{"tipo":"dialogo","titulo":"Diálogo — Check-in en Cancún","lineas":[{"quien":"Receptionist","en":"Good afternoon, welcome to Hotel Mar Azul! Are you checking in?","es":"¡Buenas tardes, bienvenidos al Hotel Mar Azul! ¿Van a registrarse?"},{"quien":"Guest","en":"Yes, we have a reservation under Johnson.","es":"Sí, tenemos una reservación a nombre de Johnson."},{"quien":"Receptionist","en":"Let me see… Yes, Mr. and Mrs. Johnson, an ocean-view room for four nights. May I see your passports, please?","es":"Déjeme ver… Sí, señor y señora Johnson, una habitación con vista al mar por cuatro noches. ¿Me permiten sus pasaportes, por favor?"},{"quien":"Guest","en":"Here you go. Is breakfast included?","es":"Aquí tiene. ¿El desayuno está incluido?"},{"quien":"Receptionist","en":"Yes, it is. It's served from 7 to 11 in the main restaurant. Here are your key cards. Your room is 512, on the fifth floor.","es":"Sí. Se sirve de 7 a 11 en el restaurante principal. Aquí están sus tarjetas-llave. Su habitación es la 512, en el quinto piso."},{"quien":"Guest","en":"What time is check-out?","es":"¿A qué hora es la salida?"},{"quien":"Receptionist","en":"Check-out is at noon. Enjoy your stay!","es":"La salida es a mediodía. ¡Disfruten su estancia!"}]},{"tipo":"tarjetas","rotulo":"Preguntas frecuentes de huéspedes","voz":true,"instruccion":"Lee la pregunta y contesta en voz alta antes de voltear.","tarjetas":[{"frente":"What's the Wi-Fi password?","reverso":"It's on the card inside your key envelope."},{"frente":"Can we get a late check-out?","reverso":"Let me check availability. I can offer you until 2 p.m."},{"frente":"Is the water safe to drink?","reverso":"We recommend bottled water. There are complimentary bottles in your room."},{"frente":"Can you call a taxi for us?","reverso":"Of course. It will be here in about ten minutes."},{"frente":"Where can I exchange money?","reverso":"There's an exchange office in the lobby, next to the gift shop."},{"frente":"The air conditioning isn't working.","reverso":"I'm sorry about that. I'll send someone from maintenance right away."}]},{"tipo":"practica","rotulo":"Elige la mejor respuesta","preguntas":[{"p":"Llega un huésped con maletas. ¿Qué dices primero?","ops":["Name?","Welcome! Are you checking in?","Wait there, please."],"correcta":1},{"p":"<i>a credit card for incidentals</i> es una tarjeta para…","ops":["pagar el vuelo","gastos adicionales durante la estancia","reservar otro hotel"],"correcta":1},{"p":"«La salida es a mediodía» se dice…","ops":["Check-out is at noon.","The exit is at midday.","Check-in is at noon."],"correcta":0},{"p":"El huésped pregunta si puede salir más tarde.","ops":["No.","Late check-out doesn't exist.","Let me check availability for a late check-out."],"correcta":2},{"p":"El huésped se queja de que no sirve el aire acondicionado.","ops":["I'm sorry about that. I'll send someone from maintenance right away.","It works for me.","That's normal in Cancún."],"correcta":0}]},{"tipo":"ordenar","rotulo":"Arma las frases de recepción","voz":true,"items":[{"frase":"May I have the name on the reservation?","es":"¿Me da el nombre de la reservación?"},{"frase":"Your room is on the fifth floor","es":"Su habitación está en el quinto piso"},{"frase":"How was your stay with us?","es":"¿Qué tal su estancia con nosotros?"}]},{"tipo":"pronunciar","rotulo":"Practica en voz alta","frases":[{"en":"Welcome to Hotel Mar Azul! Are you checking in?","pron":"uélcom tu joutél mar azúl ar iu chéking in","es":"¡Bienvenidos al Hotel Mar Azul! ¿Van a registrarse?"},{"en":"Here are your key cards.","pron":"jíer ar iór ki cards","es":"Aquí están sus tarjetas-llave."},{"en":"Enjoy your stay!","es":"¡Disfrute su estancia!"}]},{"tipo":"clave","items":["Check-in: bienvenida → reservación → identificación y pago → estancia → llave e indicaciones.","Confirma fechas y datos con <i>Is that correct?</i>; cara a cara también cuentan sonrisa y contacto visual.","Ante una falla en la habitación: disculpa + acción inmediata (<i>I'll send someone right away</i>)."]}],"c-ingles-servicio-m4-l2":[{"tipo":"texto","texto":"En un restaurante o una tienda de zona turística, la conversación es corta pero tiene momentos clave. En el <b>restaurante</b>: recibir, ofrecer bebidas, <b>recomendar</b>, preguntar por <b>alergias</b>, revisar que todo esté bien y cobrar. En la <b>tienda</b>: saludar sin presionar, ayudar a encontrar tallas o productos y cobrar. Las alergias son un tema serio: si no sabes si un platillo lleva algún ingrediente, <b>pregunta en cocina</b> antes de contestar."},{"tipo":"tabla","titulo":"Restaurante","voz":true,"colVoz":1,"encabezados":["Momento","Frase","Español"],"filas":[["Recibir","Hi! Table for how many?","¡Hola! ¿Mesa para cuántos?"],["Bebidas","Can I get you something to drink?","¿Les traigo algo de tomar?"],["Recomendar","I recommend the cochinita pibil. It's a slow-roasted pork dish from Yucatán.","Les recomiendo la cochinita pibil. Es un platillo de cerdo cocinado lentamente, de Yucatán."],["Picante","It's a little spicy. Would you like the salsa on the side?","Pica un poco. ¿Quieren la salsa aparte?"],["Alergias","Do you have any food allergies?","¿Tienen alguna alergia a algún alimento?"],["Revisar","How is everything?","¿Qué tal está todo?"],["Cobrar","Would you like to pay together or separately?","¿Quieren pagar junto o por separado?"]]},{"tipo":"tabla","titulo":"Tienda","voz":true,"colVoz":1,"encabezados":["Momento","Frase","Español"],"filas":[["Saludar sin presionar","Hi! Let me know if you need any help.","¡Hola! Si necesita ayuda, me avisa."],["Ayudar","Are you looking for anything in particular?","¿Busca algo en particular?"],["Tallas","What size are you looking for?","¿Qué talla busca?"],["Probador","The fitting rooms are over there.","Los probadores están por allá."],["Cobrar","Will that be cash or card?","¿Paga en efectivo o con tarjeta?"],["Bolsa","Would you like a bag?","¿Quiere una bolsa?"]],"nota":"En EE. UU. la ropa y el calzado usan otras tallas. Si tu tienda recibe muchos turistas, ten a la mano una tabla de equivalencias."},{"tipo":"dialogo","titulo":"Diálogo — Una mesa en Playa del Carmen","lineas":[{"quien":"Waiter","en":"Good evening! My name is Luis, and I'll be your server tonight. Can I get you something to drink?","es":"¡Buenas noches! Me llamo Luis y hoy los voy a atender. ¿Les traigo algo de tomar?"},{"quien":"Guest","en":"Two lemonades, please. What do you recommend?","es":"Dos limonadas, por favor. ¿Qué nos recomienda?"},{"quien":"Waiter","en":"The fish tacos are very popular. And if you like pork, I recommend the cochinita pibil. It's a little spicy.","es":"Los tacos de pescado son muy populares. Y si les gusta el cerdo, les recomiendo la cochinita pibil. Pica un poco."},{"quien":"Guest","en":"I'm allergic to shellfish. Do the fish tacos have shrimp?","es":"Soy alérgica a los mariscos. ¿Los tacos de pescado llevan camarón?"},{"quien":"Waiter","en":"Let me check with the kitchen to be completely sure. I'll be right back.","es":"Permítame confirmarlo en cocina para estar completamente seguro. Enseguida regreso."}]},{"tipo":"practica","rotulo":"Elige la mejor opción","preguntas":[{"p":"El cliente pregunta si un platillo tiene nuez y no estás seguro.","ops":["No, I think it's fine.","Let me check with the kitchen to be completely sure.","Probably not."],"correcta":1,"explica":"Con alergias nunca adivines: confirma en cocina."},{"p":"«¿Pagan junto o por separado?» se dice…","ops":["Do you pay together or apart?","Is it one or many bills?","Would you like to pay together or separately?"],"correcta":2},{"p":"Un cliente entra a la tienda y solo está viendo.","ops":["Hi! Let me know if you need any help.","What do you want to buy?","Follow me, please."],"correcta":0},{"p":"<i>salsa on the side</i> significa…","ops":["salsa encima","sin salsa","salsa aparte"],"correcta":2},{"p":"«¿Qué talla busca?» se dice…","ops":["Which number are you?","What size are you looking for?","How big you are?"],"correcta":1}]},{"tipo":"relacionar","rotulo":"Relaciona","voz":true,"pares":[["server","mesero o mesera"],["check / bill","cuenta"],["tip","propina"],["spicy","picante"],["fitting room","probador"],["size","talla"]]},{"tipo":"completar","rotulo":"Completa","voz":true,"items":[{"frase":"Table for how ___?","resp":["many"],"es":"¿Mesa para cuántos?"},{"frase":"Do you have any food ___?","resp":["allergies"],"es":"¿Tiene alguna alergia a algún alimento?"},{"frase":"It's a little ___. Would you like the salsa on the side?","resp":["spicy","hot"],"es":"Pica un poco. ¿Quiere la salsa aparte?"},{"frase":"Will that be cash or ___?","resp":["card","credit card"],"es":"¿Paga en efectivo o con tarjeta?"},{"frase":"The fitting ___ are over there.","resp":["rooms"],"es":"Los probadores están por allá."}]},{"tipo":"clave","items":["Restaurante: recibe → bebidas → recomienda → alergias → revisa → cobra.","Con alergias nunca adivines: <i>Let me check with the kitchen.</i>","Tienda: saluda sin presionar (<i>Let me know if you need any help</i>) y ayuda con tallas y cobro."]}],"c-ingles-servicio-m4-l3":[{"tipo":"texto","texto":"Cada vez más atención a clientes es por <b>chat</b> y <b>correo</b>. Aquí no hay tono de voz que ayude: todo depende de tus palabras. La estructura es la misma que en una llamada, pero más breve: <b>saludo con nombre → agradecimiento o empatía → solución con pasos claros → cierre</b>. Escribe frases cortas, un tema por párrafo, y revisa ortografía antes de enviar. En chat, avisa si vas a tardar: el cliente no ve que estás buscando."},{"tipo":"comparar","titulo":"Abreviaturas y estilo a evitar","malTitulo":"Demasiado informal","mal":"<i>hi, pls wait, u need to restart ur router thx</i><br><i>idk, btw ur order is late</i><br><i>WE CANNOT DO THAT.</i> (mayúsculas = gritar)<br><i>np!!! :)))</i>","bienTitulo":"Profesional y cordial","bien":"<i>Hi Sarah, thank you for your patience.</i><br><i>Please restart your router and let me know if the light turns green.</i><br><i>Let me check that for you.</i><br><i>You're welcome! Have a great day.</i>"},{"tipo":"tabla","titulo":"Frases útiles para chat","voz":true,"colVoz":1,"encabezados":["Para…","Frase","Español"],"filas":[["Saludar","Hi Sarah, thanks for reaching out!","Hola Sarah, ¡gracias por contactarnos!"],["Avisar que tardas","Please give me a moment while I check your account.","Deme un momento mientras reviso su cuenta."],["Regresar","Thank you for waiting.","Gracias por esperar."],["Dar pasos","First, go to Settings. Then, tap \"Reset network.\"","Primero, entre a Configuración. Después, toque «Reset network»."],["Confirmar","Did that solve the issue?","¿Eso resolvió el problema?"],["Cerrar","Is there anything else I can help you with?","¿Hay algo más en lo que le pueda ayudar?"]]},{"tipo":"plantilla","rotulo":"Plantilla — Correo de respuesta a una queja","texto":"Subject: Re: Damaged item – Order #58213\n\nHi Mr. Thompson,\n\nThank you for contacting us, and I am sorry to hear that your coffee maker arrived damaged. I understand how frustrating that must be.\n\nI have arranged a replacement at no cost to you. Here is what happens next:\n\n1. You will receive a prepaid return label by email today.\n2. Please use it to send back the damaged item within 14 days.\n3. We will ship your new coffee maker as soon as the return is scanned.\n\nYour case number is 58213-R. If you have any questions, simply reply to this email.\n\nThank you for your patience.\n\nBest regards,\n\nMariana López\nCustomer Support Team","nota":"Cambia nombre, producto, pasos y plazos por los reales de tu empresa. Observa: empatía al inicio, pasos numerados y un cierre con número de caso."},{"tipo":"plantilla","rotulo":"Plantilla — Respuestas rápidas de chat","texto":"Saludo: Hi [name], thanks for reaching out! My name is [your name]. How can I help you today?\n\nEspera: Please give me a moment while I check your account.\n\nRegreso: Thank you for waiting, [name].\n\nNo sé la respuesta: That is a great question. Let me confirm with my team and get back to you in a few minutes.\n\nCierre: Is there anything else I can help you with today? Thank you for chatting with us, and have a great day!","nota":"Personaliza siempre el nombre y adapta la frase al caso: una respuesta rápida copiada sin revisar se nota."},{"tipo":"practica","rotulo":"¿Cuál mensaje enviarías?","preguntas":[{"p":"Necesitas unos minutos para revisar la cuenta.","ops":["wait","Please give me a moment while I check your account.","BRB"],"correcta":1},{"p":"Quieres dar instrucciones.","ops":["u need to restart ur phone","RESTART YOUR PHONE NOW.","First, restart your phone. Then, open the app again."],"correcta":2},{"p":"El cliente te da las gracias.","ops":["You're welcome! Have a great day.","np","k"],"correcta":0},{"p":"¿Por qué evitar escribir todo en mayúsculas?","ops":["Porque en internet se lee como si gritaras","Porque gasta más tinta","Porque es más difícil de escribir"],"correcta":0},{"p":"¿Qué va primero en un correo de respuesta a una queja?","ops":["El número de caso sin saludo","Saludo con nombre y una frase de empatía","Las políticas de la empresa"],"correcta":1}]},{"tipo":"completar","rotulo":"Completa el chat","voz":true,"items":[{"frase":"Hi Sarah, thanks for reaching ___!","resp":["out"],"es":"Hola Sarah, ¡gracias por contactarnos!"},{"frase":"Please give me a ___ while I check your account.","resp":["moment","minute"],"es":"Deme un momento mientras reviso su cuenta."},{"frase":"Thank you for ___.","resp":["waiting","your patience"],"es":"Gracias por esperar."},{"frase":"Did that ___ the issue?","resp":["solve","fix","resolve"],"es":"¿Eso resolvió el problema?"},{"frase":"Thank you for ___ with us!","resp":["chatting"],"es":"¡Gracias por chatear con nosotros!"}]},{"tipo":"clave","items":["Estructura: saludo con nombre → empatía → solución en pasos → cierre.","Evita <i>u, ur, pls, thx, idk, np</i> y las mayúsculas sostenidas.","En chat, avisa cuando vas a tardar y regresa con <i>Thank you for waiting.</i>"]}],"c-ingles-servicio-m4-l4":[{"tipo":"texto","texto":"Para entrar a un call center bilingüe normalmente pasas por <b>dos filtros</b>: una <b>entrevista</b> (con reclutamiento o con un supervisor, a veces toda en inglés) y una <b>evaluación de inglés</b>. Cada empresa tiene su propio proceso y no hay un formato único; aquí te explicamos en general qué se suele revisar para que llegues preparado. Desconfía de quien te pida dinero para «asegurarte» un puesto o pasar el examen."},{"tipo":"tabla","titulo":"Preguntas típicas de entrevista","voz":true,"colVoz":1,"encabezados":["Pregunta","Cómo empezar tu respuesta","Consejo"],"filas":[["Tell me about yourself.","I'm… I've worked in… I'm looking for…","Presente, experiencia y por qué este puesto. Un minuto."],["Why do you want to work in customer service?","I enjoy helping people and solving problems…","Da un ejemplo real, no solo «por el sueldo»."],["How would you handle an angry customer?","First, I would listen without interrupting…","Usa el orden del módulo 2: escuchar, empatía, solución."],["Tell me about a time you solved a problem.","In my last job, a customer… I… As a result…","Situación, lo que hiciste y el resultado."],["Are you available to work nights or weekends?","Yes, I'm available… / I'm available on…","Sé honesto sobre tus horarios."],["Do you have any questions for us?","Yes. What does the training look like?","Siempre lleva una o dos preguntas."]]},{"tipo":"dialogo","titulo":"Diálogo — Entrevista en Guadalajara","lineas":[{"quien":"Recruiter","en":"Tell me about yourself.","es":"Háblame de ti."},{"quien":"Candidate","en":"I'm Karla. I've worked as a cashier at a department store for two years, and I use English with tourists almost every day. Now I'm looking for a job where I can use my English full-time.","es":"Soy Karla. Llevo dos años como cajera en una tienda departamental y uso el inglés con turistas casi a diario. Ahora busco un trabajo donde pueda usar mi inglés de tiempo completo."},{"quien":"Recruiter","en":"How would you handle an angry customer?","es":"¿Cómo manejarías a un cliente molesto?"},{"quien":"Candidate","en":"First, I would listen without interrupting. Then I would show empathy, apologize for the problem and offer a solution. If I couldn't solve it, I would ask my supervisor for help.","es":"Primero escucharía sin interrumpir. Después mostraría empatía, me disculparía por el problema y ofrecería una solución. Si no pudiera resolverlo, le pediría ayuda a mi supervisor."},{"quien":"Recruiter","en":"Great. Do you have any questions for us?","es":"Muy bien. ¿Tienes alguna pregunta para nosotros?"},{"quien":"Candidate","en":"Yes. What does the training look like for new agents?","es":"Sí. ¿Cómo es la capacitación para los agentes nuevos?"}]},{"tipo":"lista","items":["<b>Qué se suele evaluar</b> (cada empresa combina estas partes a su manera): comprensión auditiva, lectura, gramática y vocabulario, expresión oral y, a veces, redacción.","<b>Formatos comunes:</b> una prueba en computadora o por teléfono, una conversación con un reclutador en inglés y, con frecuencia, un <b>role play</b>: el reclutador hace de cliente y tú de agente.","<b>En la parte oral</b> suelen fijarse en que te entiendan, en tu fluidez, en que contestes lo que te preguntan y en tu tono con el «cliente».","<b>Otras pruebas posibles:</b> velocidad de escritura en teclado, uso básico de computadora y redacción de un correo o chat breve.","<b>Cómo practicar con este curso:</b> repite los diálogos en voz alta, grábate con la reflexión del módulo 3 y ensaya el role play de una queja completa."]},{"tipo":"practica","rotulo":"Mini examen de práctica","preguntas":[{"p":"<b>Comprensión.</b> El cliente dice: <i>I was charged twice for my May bill.</i> ¿Cuál es el problema?","ops":["No le llegó la factura de mayo","Le cobraron dos veces la factura de mayo","Quiere pagar dos meses"],"correcta":1},{"p":"<b>Gramática.</b> <i>I ___ here since 2022.</i>","ops":["have worked","work","am working","worked"],"correcta":0},{"p":"<b>Vocabulario.</b> <i>I'm going to escalate your case</i> significa…","ops":["Voy a cerrar su caso","Voy a borrar su caso","Voy a pasar su caso a un nivel superior"],"correcta":2},{"p":"<b>Role play.</b> El «cliente» dice: <i>This is the second time I'm calling!</i> ¿Qué respondes?","ops":["OK. What do you want?","That's not my problem.","Calm down, please.","I'm sorry you had to call again. Let me make sure we fix it today."],"correcta":3},{"p":"<b>Redacción.</b> ¿Cuál es el mejor inicio de un chat?","ops":["Hi Tom, thanks for reaching out! How can I help you today?","hi, wat u need?","WELCOME. STATE YOUR PROBLEM."],"correcta":0},{"p":"<b>Entrevista.</b> Te preguntan <i>Do you have any questions for us?</i>","ops":["No.","Yes. What does the training look like?","How much is the salary? Nothing else."],"correcta":1}]},{"tipo":"reflexion","rotulo":"Prepara tus respuestas","pregunta":"Escribe en inglés tus respuestas a tres preguntas: <i>Tell me about yourself</i>, <i>How would you handle an angry customer?</i> y <i>Tell me about a time you solved a problem.</i> Cada una de 3 a 5 frases. Después dilas en voz alta, sin leer, y grábate. Ensaya también un role play completo con alguien de confianza: tú eres el agente y la otra persona hace de cliente molesto.","ayuda":"I'm… I've worked… I'm looking for… First, I would listen… In my last job, a customer… I… As a result…"},{"tipo":"pronunciar","rotulo":"Practica en voz alta","frases":[{"en":"I enjoy helping people and solving problems.","pron":"ai enyói jélping pípol and sólving próblems","es":"Me gusta ayudar a la gente y resolver problemas."},{"en":"First, I would listen without interrupting.","pron":"ferst ai uud lísen uizáut interápting","es":"Primero escucharía sin interrumpir."},{"en":"What does the training look like?","es":"¿Cómo es la capacitación?"}]},{"tipo":"clave","items":["Prepara <i>Tell me about yourself</i>, el cliente molesto y un ejemplo real de problema resuelto.","La evaluación de inglés cambia según la empresa; suele revisar comprensión, gramática, expresión oral y a veces redacción y role play.","Practica en voz alta y grábate: se evalúa sobre todo que te entiendan y que respondas lo que te preguntan."]}]},"q":{"c-ingles-servicio-m1":[{"p":"¿Cuál es una apertura de guion completa?","ops":["Hello, tell me.","Thank you for calling BlueRiver. My name is Ana. How may I help you today?","BlueRiver, what do you need?","Yes? Ana speaking."],"correcta":1},{"p":"Contestas a las 9 p. m. ¿Qué saludo usas?","ops":["Good evening","Good night","Good afternoon"],"correcta":0},{"p":"¿Cuál es la forma más cortés de pedir un dato?","ops":["Tell me your birthday.","Birthday?","I need your birthday now.","Could you verify your date of birth for me?"],"correcta":3},{"p":"En el alfabeto NATO, <i>V</i> es…","ops":["Victory","Violet","Victor","Vector"],"correcta":2},{"p":"Un cliente de EE. UU. escribe <i>10/02/2026</i>. ¿Qué fecha es?","ops":["10 de febrero de 2026","2 de octubre de 2026","20 de octubre de 2026"],"correcta":1},{"p":"¿Cómo se dice <i>$34.50</i> de forma natural?","ops":["thirty-four fifty","three four five zero","thirty-four point five","thirty and four fifty"],"correcta":0},{"p":"¿Qué dices antes de poner a alguien en espera?","ops":["Hold.","Wait a second, please wait.","Don't go.","May I place you on a brief hold?"],"correcta":3},{"p":"¿Qué preguntas antes de despedirte?","ops":["Is there anything else I can help you with today?","Why did you call?","Can I go now?"],"correcta":0}],"c-ingles-servicio-m2":[{"p":"¿Cuál es el orden recomendado ante una queja?","ops":["Solución → empatía → escuchar","Escuchar → parafrasear → empatía → acción","Explicar la política → colgar","Empatía → colgar → escuchar"],"correcta":1},{"p":"¿Cuál frase es correcta?","ops":["I understand how frustrating must be that.","I understand how is frustrating that.","I understand how frustrating that must be."],"correcta":2},{"p":"¿Cuál es una disculpa profesional?","ops":["The system did it, not me.","I apologize for the delay with your order.","Sorry, that's life.","You should have called before."],"correcta":1},{"p":"Una frase de lenguaje positivo es…","ops":["What I can do is…","We can't, it's the policy.","That's not my department."],"correcta":0},{"p":"¿Qué frase evitarías con un cliente molesto?","ops":["Let me see what options we have.","I'm sorry this happened.","I understand this is upsetting.","Calm down."],"correcta":3},{"p":"No sabes cuándo exactamente llega el paquete. ¿Qué dices?","ops":["It will arrive tomorrow for sure.","It should arrive in three to five business days.","Maybe never."],"correcta":1},{"p":"«Voy a escalar esto con mi supervisor» se dice…","ops":["I will up this to my boss.","I pass you to boss.","I'm going to climb this.","I'm going to escalate this to my supervisor."],"correcta":3},{"p":"El cliente insulta. ¿Qué es lo más adecuado?","ops":["I want to help you, but I need us to keep this respectful.","Insultarlo de regreso","Colgar sin decir nada"],"correcta":0}],"c-ingles-servicio-m3":[{"p":"¿Cuál es una pregunta abierta?","ops":["Do you have a car?","Is it for you?","What will you mainly use it for?","Are you at home?"],"correcta":2},{"p":"¿Qué conviene hacer antes de recomendar un plan?","ops":["Preguntar y confirmar lo que necesita el cliente","Leer todos los planes disponibles","Ofrecer el más caro"],"correcta":0},{"p":"¿Cuál frase describe un beneficio?","ops":["It has 256 GB.","You can store all your family photos without deleting any.","It is silver."],"correcta":1},{"p":"El cliente rechaza el complemento. ¿Qué dices?","ops":["Are you really sure?","You will regret it.","This offer is only today.","No problem at all."],"correcta":3},{"p":"<i>It may take five to seven business days</i> significa…","ops":["Puede tardar de cinco a siete días hábiles","Tarda cinco o siete semanas","Llega en siete días de negocio del cliente"],"correcta":0},{"p":"<i>Your order is out for delivery</i> significa…","ops":["Su pedido se canceló","Su pedido está en ruta de entrega","Su pedido está agotado"],"correcta":1},{"p":"Sobre la pronunciación en un call center, lo más importante es…","ops":["Hablar muy rápido para sonar nativo","Eliminar todo rastro de acento","Imitar el acento de una ciudad de EE. UU.","Que te entiendan a la primera"],"correcta":3},{"p":"<i>Can I help you?</i> enlazado suena como…","ops":["can-i-help-you, separado","ca-nai-help-you","can-help-I-you"],"correcta":1}],"c-ingles-servicio-m4":[{"p":"¿Qué dices al recibir a un huésped con maletas?","ops":["Name, please.","Wait.","Welcome! Are you checking in?","Room?"],"correcta":2},{"p":"<i>Check-out is at noon</i> significa…","ops":["La salida es a mediodía","La entrada es a mediodía","La salida es a medianoche"],"correcta":0},{"p":"Un comensal pregunta si un platillo tiene cacahuate y no estás seguro. ¿Qué haces?","ops":["Dices que no para no tardar","Le recomiendas otro sin preguntar","Dices: <i>Let me check with the kitchen to be completely sure.</i>"],"correcta":2},{"p":"«¿Pagan junto o por separado?» se dice…","ops":["Would you like to pay together or separately?","You pay one or two?","Do you want many bills?"],"correcta":0},{"p":"¿Cuál mensaje de chat es profesional?","ops":["pls w8","Please give me a moment while I check your account.","WAIT.","u ok?"],"correcta":1},{"p":"¿Por qué no escribir todo en mayúsculas en un chat?","ops":["Porque no se puede","Porque se lee como si gritaras","Porque ocupa más espacio"],"correcta":1},{"p":"¿Qué conviene incluir al responder <i>Tell me about yourself</i>?","ops":["Toda tu vida desde la infancia","Solo tu nombre","Quién eres hoy, tu experiencia y por qué quieres el puesto","Tus problemas con tu trabajo anterior"],"correcta":2},{"p":"Sobre la evaluación de inglés en un call center…","ops":["Todas las empresas usan exactamente el mismo examen","Cada empresa tiene su proceso; suele incluir comprensión, expresión oral y a veces role play","Solo se evalúa la gramática escrita"],"correcta":1}]}});
